sys_script_include.script:
var ValueMapper = Class.create();
ValueMapper.prototype = {

    initialize: function () {
        this._cache = {};
    },

    // scheme: value_map.scheme (e.g. 'acord_lob_code', 'legacy_lob', 'acord_construction').
    // reverse=true maps target -> source. Returns '' when no mapping exists unless
    // passthrough=true, in which case the input value is returned unchanged.
    map: function (scheme, value, reverse, passthrough) {
        var table = this._load(scheme);
        var key = String(value == null ? '' : value).trim();
        var hit = reverse ? table.reverse[key.toLowerCase()] : table.forward[key.toLowerCase()];
        if (hit !== undefined)
            return hit;
        return passthrough ? key : '';
    },

    has: function (scheme, value) {
        return this._load(scheme).forward[String(value).trim().toLowerCase()] !== undefined;
    },

    _load: function (scheme) {
        if (this._cache[scheme])
            return this._cache[scheme];
        var t = { forward: {}, reverse: {} };
        var gr = new GlideRecord(Constants.TABLE.VALUE_MAP);
        gr.addQuery('scheme', scheme);
        gr.addQuery('active', true);
        gr.query();
        while (gr.next()) {
            var src = String(gr.getValue('source_value') || '');
            var tgt = String(gr.getValue('target_value') || '');
            t.forward[src.toLowerCase()] = tgt;
            if (t.reverse[tgt.toLowerCase()] === undefined)
                t.reverse[tgt.toLowerCase()] = src;
        }
        this._cache[scheme] = t;
        return t;
    },

    type: 'ValueMapper'
};
